[p('Syndrome des loges aigu après traumatisme.','p83-boast-loges-0'),p('La douleur disproportionnée et celle provoquée à la mobilisation passive orientent l’examen.','p83-boast-loges-0'),p('Le document traite l’atteinte aiguë ; le syndrome chronique d’effort appartient à un autre cadre.','p83-boast-loges-0'),p('L’évaluation spécialisée est urgente et la décompression suit immédiatement le diagnostic.','p83-boast-loges-3')],
[p('Radiculopathie ou compression nerveuse associée.','c83-30'),p('La topographie, les réflexes et les déficits moteurs ou sensitifs sont confrontés aux examens indiqués.','c83-30'),p('Une douleur référée musculaire peut ressembler à un territoire radiculaire ; son dessin seul ne tranche donc pas.','c83-9','c83-30'),p('Un déficit ou une alarme sphinctérienne déclenche le parcours neurologique urgent ; les autres cas relèvent d’un bilan ciblé.','pa17-lomb22-urgence','c83-30')],
